import React, { useState, useEffect } from "react";
import axios from "axios";
import { Route, Redirect, useLocation } from "react-router-dom";
import {
  Paper,
  Backdrop,
  CircularProgress,
  Typography,
} from "@material-ui/core";

import { makeStyles } from "@material-ui/core/styles";

import "./App.css";
import PageAddress from "./PageAddress";
import NavButtons from "./NavButtons";
import PageSchools from "./PageSchools";
import PageListingInformation from "./PageListingInformation";
import PageVideos from "./PageVideos";
import PageAmenities from "./PageAmenities";
import PagePhotos from "./PagePhotos";
import PageFeaturedPhoto from "./PageFeaturedPhoto";

const useStyles = makeStyles((theme) => ({
  paper: {
    padding: theme.spacing(3),
    left: 0,
    right: 0,
  },
  header: {
    marginBottom: theme.spacing(4),
  },
  stepper: {
    marginBottom: theme.spacing(4),
  },
  container: {
    position: "relative",
  },
  backdrop: {
    zIndex: theme.zIndex.drawer + 1,
    color: "#fff",
  },
  err: {
    color: "red",
  },
}));

const fields = [
  "street",
  "line2",
  "county",
  "city",
  "state",
  "zip",
  "lat",
  "lng",
  "property_type",
  "bedrooms",
  "bathrooms",
  "square_ft",
  "price",
  "mls_no",
  "listing_status_id",
  "year_built",
  "lot_square_ft",
  "floors",
  "garage_size",
  "property_desc",
  "elementary_school",
  "middle_school",
  "high_school",
  "listing_videos",
  "amenities",
];
function App({ apiToken, apiUrl, listingId }) {
  const classes = useStyles();
  const [loading, setLoading] = useState(false);
  const [currentStepPos, setCurrentStepPos] = useState(0);
  const [allSchools, setAllSchools] = useState(null);
  const [featuredPhoto, setFeaturedPhoto] = useState(null);
  const [videos, setVideos] = useState([]);
  const [amenities, setAmenities] = useState([]);
  const [customAmenities, setCustomAmenities] = useState([]);
  const [pageIsValid, setPageIsValid] = useState(true);
  const [error, setError] = useState(null);
  // if true, pages will show validation errors
  // when Next button is clicked
  const [showErrors, setShowErrors] = useState(false);
  const [newListingId, setNewListingId] = useState("");
  const location = useLocation();
  const [listingInformation, setListingInformation] = useState({
    propertyType: "",
    bedrooms: "",
    bathrooms: "",
    squareFt: "",
    price: "",
    mlsNo: "",
    listingStatus: "",
    yearBuilt: "",
    lotSquareFt: "",
    floors: "",
    garageSize: "",
    propertyDesc: "",
  });
  const [chosenSchools, setChosenSchools] = useState({
    elementarySchool: "",
    middleSchool: "",
    highSchool: "",
  });
  const [address, setAddress] = useState({
    street: "",
    line2: "",
    county: "",
    country: "",
    city: "",
    state: "",
    zip: "",
    lat: 0,
    lng: 0,
  });

  const steps = [
    {
      title: "Property Address",
      desc: "",
      path: "/address",
      Component: PageAddress,
      props: {
        setAddress,
        address,
        saveListing,
        setPageIsValid,
        showErrors,
      },
    },
    {
      title: "Nearby Schools",
      desc:
        "School data may not auto-populate in rural areas. Feel free to type in different schools.",
      path: "/schools",
      Component: PageSchools,
      props: {
        address,
        apiToken,
        apiUrl,
        allSchools,
        setAllSchools,
        chosenSchools,
        setChosenSchools,
      },
    },
    {
      title: "Listing Information",
      desc: "",
      path: "/listing-information",
      Component: PageListingInformation,
      props: {
        listingInformation,
        setListingInformation,
      },
    },
    {
      title: "Property videos (Youtube or Vimeo links)",
      desc:
        "Paste your YouTube or Vimeo video link here. You can add up to two videos.",
      path: "/videos",
      Component: PageVideos,
      props: {
        listType: "video",
        youtubeApiKey: "AIzaSyAZiXczeIoAt6mwCXt-CUU9Z-yB4bMWBIw",
        vimeoApiKey: "8ab15256c3536301721d3bd34af0a5f0",
        label: "Video URL",
        maxItems: 2,
        items: videos,
        setItems: setVideos,
      },
    },
    {
      title: "Property Amenities",
      desc: "",
      path: "/amenities",
      Component: PageAmenities,
      props: {
        amenities,
        setAmenities,
        customAmenities,
        setCustomAmenities,
      },
    },
    {
      title: "Property Photos",
      desc: "",
      path: "/photos",
      Component: PagePhotos,
      props: {
        bulletPoints: [
          "Click UPLOAD PHOTOS or drag and drop below",
          "A maximum of 50 images can be added",
          "Drag images to reorder them",
        ],
        rkKey: listingId || newListingId,
        url: apiUrl,
        apiToken: apiToken,
        maxItems: 50,
      },
    },
    {
      title: "Featured Photo",
      desc: "Click on the photo you want to feature for this listing:",
      path: "/featured-photo",
      Component: PageFeaturedPhoto,
      props: {
        rkKey: listingId || newListingId,
        url: apiUrl,
        apiToken: apiToken,
        featuredPhoto,
        setFeaturedPhoto,
      },
    },
  ];

  useEffect(() => {
    setCurrentStepPos(
      steps.findIndex((step) => step.path === location.pathname)
    );
  }, [location]);

  // if listingId is provided, fetch listing fields
  useEffect(() => {
    if (listingId) {
      setLoading(true);
      axios({
        method: "GET",
        url: apiUrl + "/get-fields",
        params: {
          api_token: apiToken,
          id: listingId,
          fields: fields.join(","),
        },
      })
        .then((res) => res.data)
        .then((data) => {
          setAddress({
            street: data.street || "",
            line2: data.add_line2 || "",
            county: data.county || "",
            city: data.city || "",
            state: data.state || "",
            zip: data.zip || "",
            lat: data.lat || "",
            lng: data.lng || "",
          });
          setListingInformation({
            propertyType: data.property_type || "",
            bedrooms: data.bedrooms || "",
            bathrooms: data.bathrooms || "",
            squareFt: data.square_ft || "",
            price: data.price || "",
            mlsNo: data.mls_no || "",
            listingStatus: data.listing_status_id || "",
            yearBuilt: data.year_built || "",
            lotSquareFt: data.lot_square_ft || "",
            floors: data.floors || "",
            garageSize: data.garage_size || "",
            propertyDesc: data.property_desc || "",
          });
          setChosenSchools({
            elementarySchool: data.elementary_school || "",
            middleSchool: data.middle_school || "",
            highSchool: data.high_school || "",
          });
          data.listing_videos && setVideos(data.listing_videos);
          data.amenities && setAmenities(data.amenities);
          data.custom_amenities && setCustomAmenities(data.custom_amenities);
        })
        .catch((err) =>
          setError(
            "Cannot get listing information from the server. Please try again later. Sorry for the inconvenience."
          )
        )
        .finally(() => setLoading(false));
    }
  }, []);

  function saveListing(listingId) {
    if (listingId) {
      return axios({
        url: apiUrl + "/listing-parts",
        method: "POST",
        params: {
          api_token: apiToken,
          //XDEBUG_SESSION_START:'PHPSTORM',
        },
        data: {
          id: listingId,
          street: address.street,
          add_line2: address.line2,
          county: address.county,
          city: address.city,
          state: address.state,
          zip: address.zip,
          lat: address.lat,
          lng: address.lng,
          elementary_school: chosenSchools.elementarySchool,
          middle_school: chosenSchools.middleSchool,
          high_school: chosenSchools.highSchool,
          property_type: listingInformation.propertyType,
          bedrooms: listingInformation.bedrooms,
          bathrooms: listingInformation.bathrooms,
          square_ft: listingInformation.squareFt,
          price: listingInformation.price,
          mls_no: listingInformation.mlsNo,
          listing_status_id: listingInformation.listingStatus,
          year_built: listingInformation.yearBuilt,
          lot_square_ft: listingInformation.lotSquareFt,
          floors: listingInformation.floors,
          garage_size: listingInformation.garageSize,
          property_desc: listingInformation.propertyDesc,
          featured_photo_id: featuredPhoto,
          amenities: amenities,
          custom_amenities: customAmenities,
          listing_videos: videos,
        },
      })
        .then((res) => true)
        .catch((err) => console.log(err));
    } else {
      return axios({
        url: apiUrl + "/listing-parts",
        method: "POST",
        params: {
          api_token: apiToken,
        },
        data: {
          street: address.street,
          add_line2: address.line2,
          county: address.county,
          city: address.city,
          state: address.state,
          zip: address.zip,
          lat: address.lat,
          lng: address.lng,
        },
      })
        .then((res) => res.data)
        .then((data) => setNewListingId(data.id))
        .catch((err) => console.log(err));
    }
  }

  return (
    <div>
      {error && <Typography className={classes.err}>{error}</Typography>}
      <Backdrop className={classes.backdrop} open={loading}>
        <CircularProgress color="inherit" />
      </Backdrop>
      <Route path="/" exact>
        <Redirect to="/address" />
      </Route>
      <div className={classes.container}>
        {steps.map(({ title, path, Component, props, desc }) => (
          <Route exact path={path} key={path}>
            <div>
              <Paper id="component" className={classes.paper}>
                <div className={classes.header}>
                  <Typography variant="h4">{title}</Typography>
                  <Typography variant="subtitle1">{desc}</Typography>
                </div>

                <Component {...props} />
                <NavButtons
                  setLoading={setLoading}
                  steps={steps}
                  currentStepPos={currentStepPos}
                  setCurrentStepPos={setCurrentStepPos}
                  pageIsValid={pageIsValid}
                  listingId={listingId || newListingId}
                  saveListing={saveListing}
                  setShowErrors={setShowErrors}
                />
              </Paper>
            </div>
          </Route>
        ))}
      </div>
    </div>
  );
}

export default App;
