import { useRef, useState, useEffect } from "react";
import SearchBox from "./SearchBox";
import ResultBox from "./ResultBox";
import AddressForm from "./AddressForm";

function PageAddress({ setAddress, address, setPageIsValid, showErrors }) {
  const [isLoading, setIsLoading] = useState(false);
  const [searchPhrase, setSearchPhrase] = useState("");
  const [results, setResults] = useState(null);
  const [chosenAddress, setChosenAddress] = useState(null);
  const [errors, setErrors] = useState({});
  const sessionToken = useRef(null);
  const googleApiKey = "AIzaSyAZiXczeIoAt6mwCXt-CUU9Z-yB4bMWBIw";

  const fieldValidations = {
    street: 80, // chars
    line2: 80,
    county: 40,
    city: 40,
    state: 2,
    zip: 5,
  };

  function handleChange(e) {
    setSearchPhrase(e.target.value);
  }

  function checkValidaty(field, value) {
    return value.length <= fieldValidations[field];
  }
  function handleAddressFieldChange(field, value) {
    if (checkValidaty(field, value)) {
      setAddress({ ...address, [field]: value });
    }
  }

  // save the token so many keystrokes count as one session
  function initAutocomplete() {
    sessionToken.current = new window.google.maps.places.AutocompleteSessionToken();
  }

  // Check page validations
  useEffect(() => {
    for (let err in errors) {
      if (errors[err] === true) {
        return setPageIsValid(false);
      }
    }
    setPageIsValid(true);
  }, [errors]);

  // PageIsValid
  useEffect(() => {
    if (!address.street) {
      setPageIsValid(false);
    } else {
      setPageIsValid(true);
    }
  }, [address.street]);

  useEffect(() => {
    const script = loadScript(
      "https://maps.googleapis.com/maps/api/js?key=" +
        googleApiKey +
        "&libraries=places",
      initAutocomplete
    );
  }, []);

  // Load google maps external js files
  function loadScript(scriptSrc, callback) {
    let script = document.getElementById("rk-google-maps");
    if (!script) {
      script = document.createElement("script");
      script.id = "rk-google-maps";
      script.src = scriptSrc;
      document.body.appendChild(script);
      script.onload = callback;
    }
    return script;
  }

  useEffect(() => {
    if (searchPhrase.length) {
      const autocompleteService = new window.google.maps.places.AutocompleteService();
      setIsLoading(true);
      autocompleteService.getPlacePredictions(
        {
          input: searchPhrase,
          sessionToken: sessionToken.current,
        },
        processResults
      );
    }
  }, [searchPhrase]);

  useEffect(() => {
    if (chosenAddress) {
      let street = chosenAddress.street_number || "";
      street += chosenAddress.route ? " " + chosenAddress.route : "";
      const county = chosenAddress.county || "";
      const city = chosenAddress.city || "";
      const state = chosenAddress.state || "";
      const zip = chosenAddress.zip || "";
      const lat = chosenAddress.lat || "";
      const lng = chosenAddress.lng || "";
      setAddress({
        ...address,
        street,
        county,
        city,
        state,
        zip,
        lat,
        lng,
      });
    }
  }, [chosenAddress]);

  function processResults(predictions, status) {
    setIsLoading(false);
    if (status == window.google.maps.places.PlacesServiceStatus.OK) {
      setResults(predictions);
    }
  }
  function placeSelectHandle(e, placeId, poweredByGoogle) {
    e.preventDefault();
    const placesService = new window.google.maps.places.PlacesService(
      poweredByGoogle.current
    );
    placesService.getDetails(
      {
        placeId: placeId,
        fields: ["address_component", "geometry"],
        sessionToken: sessionToken.current,
      },
      (result, status) => {
        if (status === window.google.maps.places.PlacesServiceStatus.OK) {
          setChosenAddress(
            makeAddress(result.address_components, result.geometry.location)
          );
        }
        setResults(null);
        setSearchPhrase("");
        sessionToken.current = new window.google.maps.places.AutocompleteSessionToken();
      }
    );
  }

  function makeAddress(googleResultAddressComponents, googleResultGeometry) {
    const generatedAddress = {};
    // we are creating our own address fields and fill
    // generatedAddress object with corresponding data
    const addressParts = {
      street_number: "street_number",
      route: "route",
      locality: "city",
      administrative_area_level_2: "county",
      administrative_area_level_1: "state",
      country: "country",
      postal_code: "zip",
    };

    for (let component of googleResultAddressComponents) {
      if (addressParts[component.types[0]]) {
        generatedAddress[addressParts[component.types[0]]] =
          component.short_name;
      }
    }
    generatedAddress["lat"] = googleResultGeometry.lat();
    generatedAddress["lng"] = googleResultGeometry.lng();

    return generatedAddress;
  }

  return (
    <div style={{ position: "relative" }}>
      <SearchBox
        onChange={handleChange}
        isLoading={isLoading}
        searchPhrase={searchPhrase}
      ></SearchBox>
      <ResultBox
        onPlaceSelect={placeSelectHandle}
        results={results}
      ></ResultBox>
      <AddressForm
        addressFields={address}
        onAddressFieldChange={handleAddressFieldChange}
        errors={errors}
        setErrors={setErrors}
        showErrors={showErrors}
      />
    </div>
  );
}

export default PageAddress;
