import React from "react";
import { Typography, Button, Grid } from "@material-ui/core";
import {
  Delete as DeleteIcon,
  CloudUpload as UploadIcon,
} from "@material-ui/icons";
import { makeStyles } from "@material-ui/core/styles";

const useStyles = makeStyles((theme) => ({
  bulletPoints: {
    listStyle: "none",
    margin: 0,
    padding: "1rem",
  },
  input: {
    display: "none",
  },
  buttons: {
    textAlign: "right",
  },
  button: {
    marginRight: theme.spacing(2),
  },
}));

function Header(props) {
  const classes = useStyles();
  function inputChangeHandle(e) {
    const files = [...e.target.files];
    props.addFiles(files);
  }
  return (
    <Grid container>
      <Grid item xs={12} sm={6}>
        <Typography variant="h5">{props.title}</Typography>
        <ul className={classes.bulletPoints}>
          {props.bulletPoints.map((bulletPoint, index) => (
            <li key={index}>
              <Typography variant="body2">{bulletPoint}</Typography>
            </li>
          ))}
        </ul>
      </Grid>
      <Grid item xs={12} sm={6} className={classes.buttons}>
        <Button
          disabled={!props.imageLength}
          onClick={props.onRemoveAllImages}
          startIcon={<DeleteIcon />}
          color="secondary"
          variant="contained"
          className={classes.button}
        >
          Delete All
        </Button>

        <input
          accept="image/jpg,image/png,image/jpeg,image/gif,image/tif,image/tif"
          className={classes.input}
          id="contained-button-file"
          multiple
          onChange={inputChangeHandle}
          type="file"
        />
        <label htmlFor="contained-button-file">
          <Button
            variant="contained"
            color="primary"
            component="span"
            startIcon={<UploadIcon />}
          >
            {props.buttonTitle}
          </Button>
        </label>
      </Grid>
    </Grid>
  );
}

export default Header;
