import React, { useState, useRef, useEffect } from "react";
import {
  Card,
  CardActions,
  CardContent,
  CardMedia,
  Button,
  Typography,
  CircularProgress,
  Backdrop,
} from "@material-ui/core";
import { makeStyles } from "@material-ui/core/styles";

const useStyles = makeStyles((theme) => ({
  card: {
    width: 245,
    padding: theme.spacing(2),
    margin: theme.spacing(2),
    height: 245,
    position: "relative",
  },
  cardImage: {
    height: 0,
    paddingTop: "82%",
  },
  cardActions: {
    position: "absolute",
    bottom: 0,
  },
  circularProgress: {
    position: "absolute",
    left: "115px",
    top: "100px",
    zIndex: 100,
  },
}));

function Image({
  imgSrc,
  id,
  initialImageName,
  position,
  onReorderImage,
  onImageRemove,
  isLoading,
  onImageRename,
}) {
  const [showMenu, setShowMenu] = useState(false);
  const [onMenuItem, setOnMenuItem] = useState(false);
  const [onMenu, setOnMenu] = useState(false);
  const latestOnMenu = useRef(onMenu);
  const [nameChangedManually, setNameChangedManully] = useState(false);
  const latestOnMenuItem = useRef(onMenuItem);
  const [name, setName] = useState(initialImageName);
  const [deleting, setDeleting] = useState(false);
  const classes = useStyles();

  function dragStartHandle(e) {
    e.stopPropagation();
    e.dataTransfer.setData("draggedImagePos", position);
    e.dataTransfer.setData("draggedImageId", id);
  }
  function dragEnterHandle(e) {
    e.preventDefault();
    e.stopPropagation();
  }
  function dragLeaveHandle(e) {
    e.preventDefault();
    e.stopPropagation();
  }
  function dropHandle(e) {
    e.stopPropagation();
    e.preventDefault();
    onReorderImage(
      e.dataTransfer.getData("draggedImageId"),
      position,
      id,
      e.dataTransfer.getData("draggedImagePos")
    );
  }
  function dragOverHandle(e) {
    e.preventDefault();
    e.stopPropagation();
  }

  function nameChangeHandle(e) {
    setName(e.target.value);
  }
  function enterMenuHandle(e) {
    if (e.target.id === "button") {
      setOnMenu(true);
    } else {
      setOnMenuItem(true);
    }
    setShowMenu(true);
  }
  function leaveMenuHandle(e) {
    if (e.target.id === "button") {
      setOnMenu(false);
    } else {
      setOnMenuItem(false);
    }
    setTimeout(() => {
      if (!latestOnMenu.current && !latestOnMenuItem.current) {
        setShowMenu(false);
      }
    }, 100);
  }
  useEffect(() => {
    latestOnMenu.current = onMenu;
    latestOnMenuItem.current = onMenuItem;
  }, [onMenu, onMenuItem]);

  // server name change after couple seconds of name change
  useEffect(() => {
    const timeoutId = setTimeout(() => {
      if (nameChangedManually) {
        onImageRename(name, id);
      }
    }, 2000);
    return () => clearTimeout(timeoutId);
  }, [name]);

  return (
    <div>
      <Card
        draggable
        onDragStart={dragStartHandle}
        onDragEnter={dragEnterHandle}
        onDragLeave={dragLeaveHandle}
        onDrop={dropHandle}
        onDragOver={dragOverHandle}
        className={classes.card}
      >
        {(isLoading || deleting) && (
          <div className={classes.circularProgress}>
            <CircularProgress />
          </div>
        )}
        <CardMedia
          image={imgSrc}
          draggable="false"
          className={classes.cardImage}
          style={isLoading || deleting ? { opacity: 0.5 } : { opacity: 1 }}
        />
        <CardContent></CardContent>
        <CardActions className={classes.cardActions}>
          <Button
            size="small"
            color="primary"
            disabled={isLoading || deleting}
            onClick={(e) => {
              setDeleting(true);
              onImageRemove(id).then((res) => setDeleting(false));
            }}
          >
            Delete
          </Button>
        </CardActions>
      </Card>
    </div>
  );
}

export default Image;
