import React, { useEffect, useState } from "react";
import {
  Card,
  CardHeader,
  CardMedia,
  CardContent,
  CardActionArea,
  IconButton,
  Typography,
} from "@material-ui/core";
import { Close as CloseIcon } from "@material-ui/icons";
import { makeStyles } from "@material-ui/core/styles";
import axios from "axios";
import videoPlaceholder from "./video_placeholder.png";
import times from "./times.svg";

const useStyles = makeStyles((theme) => ({
  container: {
    maxWidth: 345,
    margin: theme.spacing(2),
  },
  media: {
    height: 0,
    paddingTop: "56.25%", //16:9
  },
}));

function Video({ video, onRemoveItem, youtubeApiKey, vimeoApiKey }) {
  const [fetched, setFetched] = useState(null);
  const [videoDetails, setVideoDetails] = useState(null);
  const [fetchError, setFetchError] = useState(null);
  const [url, setUrl] = useState(null);
  const classes = useStyles();

  const videoThumbnail = videoDetails
    ? videoDetails.thumbnail
    : videoPlaceholder;
  useEffect(() => {
    if (video.provider === "vimeo") {
      setUrl("https://vimeo.com/" + video.videoId);
      axios
        .get("https://api.vimeo.com/videos/" + video.videoId, {
          headers: {
            Authorization: "bearer " + vimeoApiKey,
          },
        })
        .then((res) => res.data)
        .then((data) => {
          setVideoDetails({
            thumbnail: data.pictures.sizes[3].link,
            title: data.name,
            description: data.description.slice(0, 120) + "...",
          });
          setFetched(true);
        })
        .catch((err) => {
          console.log(err);
          setFetchError("Error getting details of this video");
          setFetched(true);
        });
    } else if (video.provider === "youtube") {
      setUrl("https://youtu.be/" + video.videoId);
      axios
        .get("https://www.googleapis.com/youtube/v3/videos", {
          params: {
            part: "snippet",
            id: video.videoId,
            key: youtubeApiKey,
          },
        })
        .then((res) => res.data.items[0])
        .then((data) => {
          setVideoDetails({
            thumbnail: data.snippet.thumbnails.high.url,
            title: data.snippet.title,
            description: data.snippet.description.slice(0, 150) + "...",
          });
          setFetched(true);
        })
        .catch((err) => {
          setFetchError("Error getting details of this video");
          setFetched(true);
        });
    }
  }, []);

  return (
    <Card className={classes.container}>
      <CardHeader
        title={videoDetails ? videoDetails.title : url}
        titleTypographyProps={{ variant: "subtitle1" }}
        subheader={fetchError}
        subheaderTypographyProps={{ color: "error", variant: "subtitle2" }}
        action={
          <IconButton onClick={() => onRemoveItem(video.videoId)}>
            <CloseIcon />
          </IconButton>
        }
      />
      <CardActionArea component="a" href={url} target="_blank">
        <CardMedia
          className={classes.media}
          image={videoThumbnail}
          title={videoDetails ? videoDetails.title : url}
        />
        <CardContent>
          <Typography variant="body2" color="textSecondary" component="p">
            {videoDetails ? videoDetails.description : ""}
          </Typography>
        </CardContent>
      </CardActionArea>
    </Card>
  );
}

export default Video;
