import React, { useState } from "react";
import { Redirect, useHistory } from "react-router-dom";
import {
  Button,
  Typography,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
} from "@material-ui/core";
import { Save as SaveIcon } from "@material-ui/icons";
import { makeStyles } from "@material-ui/core/styles";

const useStyles = makeStyles((theme) => ({
  buttonGroup: {
    marginTop: theme.spacing(3),
    display: "flex",
    justifyContent: "space-between",
  },
  button: {
    marginLeft: theme.spacing(3),
  },
  errContainer: {
    textAlign: "right",
  },
  err: {
    color: "red",
  },
}));

function NavButtons({
  setLoading,
  steps,
  currentStepPos,
  setCurrentStepPos,
  pageIsValid,
  listingId,
  saveListing,
  setShowErrors, // show errors on current page displaying
}) {
  const classes = useStyles();
  const history = useHistory();
  const lastStep = currentStepPos + 1 >= steps.length;
  const firstStep = currentStepPos === 0;
  // show error message in this component
  const [showError, setShowError] = useState(false);
  const [showDialog, setShowDialog] = useState(false);

  function handleNext(e) {
    if (!pageIsValid) {
      // to show errors on current page
      setShowErrors(true);

      // show error message in this component
      setShowError(true);
      setTimeout(() => setShowError(false), 4000);
      return;
    }
    if (firstStep && listingId === "") {
      setLoading(true);
      saveListing(null).finally(() => {
        setLoading(false);
        const nextStep = steps[currentStepPos + 1];
        history.push(nextStep.path);
        setCurrentStepPos(currentStepPos + 1);
      });
    } else if (lastStep) {
      setLoading(true);
      saveListing(listingId).finally(() => {
        setLoading(true);
        window.location = "/users/dashboard";
      });
    } else {
      const nextStep = steps[currentStepPos + 1];
      history.push(nextStep.path);
      setCurrentStepPos(currentStepPos + 1);
    }
  }

  function handleBack(e) {
    if (firstStep && listingId) {
      return setShowDialog(true);
    }
    if (firstStep) {
      window.location = "/users/dashboard";
    } else {
      const prevStep = steps[currentStepPos - 1];
      history.push(prevStep.path);
      setCurrentStepPos(currentStepPos - 1);
    }
  }

  function handleSave(e) {
    setShowDialog(false);
    setLoading(true);
    saveListing(listingId).finally(() => {
      setLoading(false);
      window.location = "/users/dashboard";
    });
  }
  function handleDialogClose(e) {
    setShowDialog(false);
  }

  return (
    <>
      <Dialog open={showDialog} onClose={handleDialogClose}>
        <DialogTitle>Do you want to save the changes?</DialogTitle>
        <DialogContent>
          <DialogContentText>
            You're about to leave this page, your changes will be lost. Do you
            want to save the changes?
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={() => (window.location = "/users/dashboard")}
            color="secondary"
          >
            Discard the changes
          </Button>
          <Button onClick={handleSave} color="primary">
            Save and Exit
          </Button>
        </DialogActions>
      </Dialog>
      <div className={classes.errContainer}>
        <div className={classes.buttonGroup}>
          <div>
            <Button
              color="primary"
              onClick={handleSave}
              disabled={firstStep}
              className={classes.button}
              startIcon={<SaveIcon />}
            >
              Save and Continue Later
            </Button>
          </div>
          <div>
            <Button
              variant="outlined"
              color="primary"
              onClick={handleBack}
              className={classes.button}
            >
              {firstStep ? "Cancel" : "Back"}
            </Button>
            <Button
              variant="contained"
              color="primary"
              className={classes.button}
              onClick={handleNext}
            >
              {lastStep ? "Finish" : "Next"}
            </Button>
          </div>
        </div>
        {showError && (
          <Typography className={classes.err}>
            Please fix the errors on the page
          </Typography>
        )}
      </div>
    </>
  );
}

export default NavButtons;
