import React, { useEffect, useState } from "react";
import { makeStyles } from "@material-ui/core/styles";
import { TextField, Grid, MenuItem } from "@material-ui/core";
import NumberFormat from "react-number-format";

const useStyles = makeStyles((theme) => ({
  form: {
    marginTop: theme.spacing(3),
  },
}));

// Custom react-number-format component
function ZipFormat(props) {
  const { inputRef, onChange, ...other } = props;
  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            name: props.name,
            value: values.value,
          },
        });
      }}
      format="#####"
    />
  );
}

function AddressForm({
  onAddressFieldChange,
  addressFields: { street, line2, county, city, state, zip },
  errors,
  setErrors,
  showErrors,
}) {
  const classes = useStyles();
  const [dirty, setDirty] = useState({});
  const states = [
    "AL",
    "AK",
    "AZ",
    "AR",
    "CA",
    "CO",
    "CT",
    "DE",
    "FL",
    "GA",
    "HI",
    "ID",
    "IL",
    "IN",
    "IA",
    "KS",
    "KY",
    "LA",
    "ME",
    "MD",
    "MA",
    "MI",
    "MN",
    "MS",
    "MO",
    "MT",
    "NE",
    "NV",
    "NH",
    "NJ",
    "NM",
    "NY",
    "NC",
    "ND",
    "OH",
    "OK",
    "OR",
    "PA",
    "RI",
    "SC",
    "SD",
    "TN",
    "TX",
    "UT",
    "VT",
    "VA",
    "WA",
    "WV",
    "WI",
    "WY",
  ];

  useEffect(() => {
    if (dirty.street || (showErrors && street === "")) {
      setErrors({ ...errors, street: street === "" });
    }
  }, [street, dirty, showErrors]);

  return (
    <div className={classes.form}>
      <Grid container spacing={2}>
        <Grid item xs={12}>
          <TextField
            fullWidth
            label="Street"
            value={street}
            error={errors.street}
            helperText={errors.street && "Street is required"}
            onChange={(e) => {
              setDirty({ ...dirty, street: true });
              onAddressFieldChange("street", e.target.value);
            }}
            variant="outlined"
            size="small"
            InputLabelProps={{ shrink: street !== "" }}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            label="Apt, Unit, ..."
            value={line2}
            onChange={(e) => onAddressFieldChange("line2", e.target.value)}
            variant="outlined"
            size="small"
            InputLabelProps={{ shrink: line2 !== "" }}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            label="County"
            value={county}
            onChange={(e) => onAddressFieldChange("county", e.target.value)}
            variant="outlined"
            size="small"
            InputLabelProps={{ shrink: county !== "" }}
          />
        </Grid>
        <Grid item xs={12} sm={4}>
          <TextField
            fullWidth
            label="City"
            value={city}
            onChange={(e) => onAddressFieldChange("city", e.target.value)}
            variant="outlined"
            size="small"
            InputLabelProps={{ shrink: city !== "" }}
          />
        </Grid>
        <Grid item xs={12} sm={4}>
          <TextField
            select
            fullWidth
            label="State"
            value={state}
            onChange={(e) => onAddressFieldChange("state", e.target.value)}
            variant="outlined"
            size="small"
            InputLabelProps={{ shrink: state !== "" }}
          >
            {states.map((state) => (
              <MenuItem value={state} key={state}>
                {state}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
        <Grid item xs={12} sm={4}>
          <TextField
            fullWidth
            label="ZIP Code"
            value={zip}
            onChange={(e) => onAddressFieldChange("zip", e.target.value)}
            variant="outlined"
            size="small"
            InputProps={{
              inputComponent: ZipFormat,
            }}
            InputLabelProps={{ shrink: zip !== "" }}
          />
        </Grid>
      </Grid>
    </div>
  );
}

export default AddressForm;
