import React, { useState, useEffect, useReducer } from "react";
import Image from "./Image.js";
import axios from "axios";
import Header from "./Header";
import DragZone from "./DragZone";
import {
  CircularProgress,
  Backdrop,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  Button,
} from "@material-ui/core";
import { makeStyles } from "@material-ui/core/styles";

const useStyles = makeStyles((theme) => ({
  images: {
    display: "flex",
    flexWrap: "wrap",
  },
  backdrop: {
    zIndex: theme.zIndex.drawer,
  },
}));

const MAX_FILE_SIZE_MB = 5;
const MAX_FILE_SIZE = MAX_FILE_SIZE_MB * 1024 * 1024;

function RKImageUploader(props) {
  const title = props.title || "Photo Gallery";
  const buttonTitle = props.buttonTitle || "Upload Photos";
  const [images, imageDispatch] = useReducer(imageReducer, []);
  const [isLoading, setIsLoading] = useState(true);
  const [err, setErr] = useState("");
  const maxItems = props.maxItems || 10;
  const classes = useStyles();

  const bulletPoints = props.bulletPoints || [
    "Lorem, ipsum dolor.",
    "Ducimus, unde dolorem.",
    "Commodi, culpa eum.",
  ];

  function imageReducer(images, action) {
    let localImages;
    switch (action.type) {
      case "set":
        return [...action.images];
      case "add":
        return [
          ...images,
          {
            src: action.image.src,
            id: action.image.id,
            name: action.image.name,
            position: action.image.position,
            tempId: action.image.id,
          },
        ];
      case "setId":
        localImages = [...images];
        const index = localImages.findIndex(
          (image) => image.tempId === action.tempId
        );
        localImages[index].id = action.id;
        return [...localImages];
      case "reorder":
        localImages = [...images];
        const id1 = images.findIndex((image) => image.id == action.id1);
        const id2 = images.findIndex((image) => image.id == action.id2);
        localImages[id1].position = parseInt(action.pos1);
        localImages[id2].position = parseInt(action.pos2);
        return [...localImages];
      case "remove":
        return images.filter((image) => image.id != action.id);
      case "removeAll":
        return [];
    }
  }

  function removeAllImagesHandle() {
    if (
      window.confirm(
        "Are you sure you want to remove all images uploaded, you cannot undo this?"
      )
    ) {
      setIsLoading(true);
      axios({
        method: "delete",
        url: "/image-api/",
        baseURL: props.url,
        headers: {
          "Content-Type": "application/json",
        },
        params: {
          key: props.rkKey,
          api_token: props.apiToken,
        },
        data: JSON.stringify({
          key: props.rkKey,
        }),
      })
        .then((res) => {
          if (!res.data.err) {
            imageDispatch({ type: "removeAll" });
          } else {
            setErr(
              "An error happened, please try again later. Sorry for the inconvenience."
            );
            console.error(res.data.err);
          }
        })
        .catch((err) => {
          setErr(
            "An error happened, please try again later. Sorry for the inconvenience."
          );
          console.error(err);
        })
        .finally(() => setIsLoading(false));
    }
  }

  // Download images that already exits on the server
  useEffect(() => {
    axios({
      method: "get",
      url: "/image-api",
      baseURL: props.url,
      params: {
        api_token: props.apiToken,
        key: props.rkKey,
      },
    })
      .then((res) => res.data)
      .then((imagesJson) => {
        for (let i = 0; i < imagesJson.length; i++) {
          imagesJson[i].src = "/" + imagesJson[i].image_url;
        }
        imagesJson.length && imageDispatch({ type: "set", images: imagesJson });
      })
      .catch((err) => console.error(err))
      .finally(() => setIsLoading(false));
  }, []);

  function removeImageHandle(id) {
    return axios({
      method: "delete",
      url: "/image-api/" + id,
      baseURL: props.url,
      headers: {
        "Content-Type": "applications/json",
      },
      params: {
        key: props.rkKey,
        api_token: props.apiToken,
      },
    })
      .then((res) => res.data)
      .then((res) => {
        if (!res.err) imageDispatch({ type: "remove", id });
      })
      .catch((err) => false);
  }

  function reorderImageHandle(id1, pos1, id2, pos2) {
    setIsLoading(true);
    axios({
      method: "put",
      url: "/image-api/reorder",
      baseURL: props.url,
      headers: {
        "Content-Type": "application/json",
      },
      params: {
        key: props.rkKey,
        api_token: props.apiToken,
      },
      data: JSON.stringify({
        id1,
        pos1,
        id2,
        pos2,
      }),
    })
      .then((res) => res.data)
      .then((data) => {
        if (!data.err) {
          imageDispatch({
            type: "reorder",
            id1,
            pos1,
            id2,
            pos2,
          });
        }
      })
      .catch((err) => console.log(err))
      .finally(() => setIsLoading(false));
  }
  function getHighestPosition() {
    return images
      .map((el) => el.position)
      .reduce((a, b) => {
        return Math.max(a, b);
      }, 0);
  }
  function addFiles(files) {
    let length = images.length;
    let position = getHighestPosition();
    let filesLargerThanAllowedSize = [];
    try {
      if (files.length + images.length > maxItems) {
        throw new MaxItemsReachedException(
          `Maximum of ${maxItems} can be added`
        );
      }
      files.forEach((file) => {
        if (file.size > MAX_FILE_SIZE) {
          const sizeInMb = file.size / 1024 / 1024;
          filesLargerThanAllowedSize.push({
            name: file.name,
            size: sizeInMb.toFixed(2) + "MB",
          });
          return;
        }
        position++;
        const reader = new FileReader();
        reader.readAsDataURL(file);

        const tempId = "_" + Math.random().toString(36).substr(2, 9);
        ((pos) =>
          (reader.onloadend = function () {
            imageDispatch({
              type: "add",
              image: {
                src: reader.result,
                id: tempId,
                name: file.name,
                position: pos,
              },
            });
          }))(position);
        const formData = new FormData();
        formData.append("image", file);
        formData.append("key", props.rkKey);
        formData.append("name", file.name);
        formData.append("position", position);
        axios({
          method: "post",
          url: "/image-api",
          baseURL: props.url,
          data: formData,
          params: {
            api_token: props.apiToken,
          },
          headers: { "Content-Type": "multipart/form-data" },
        })
          .then((res) => res.data)
          .then((res) =>
            imageDispatch({
              type: "setId",
              id: res.id,
              tempId,
            })
          )
          .catch((err) => {
            console.log(err);
            setErr(
              "An error happened, please try again later. Sorry for the inconvenience."
            );
            imageDispatch({
              type: "remove",
              id: tempId,
            });
          });
      });
    } catch (e) {
      if (e instanceof MaxItemsReachedException)
        setErr(`Maximum ${props.maxItems} can be added at a time`);
    }
    if (filesLargerThanAllowedSize.length > 0) {
      setErr(
        "Some of the images are larger than " +
          MAX_FILE_SIZE_MB +
          "MB. Please reduce the file size and try again: <br><br>Files that are larger than max allowed:<ul>" +
          filesLargerThanAllowedSize.map(
            (file) => "<li>" + file.name + " (" + file.size + ")</li>"
          ) +
          "</ul>"
      );
    }
  }
  function imageRenameHandle(name, id) {
    if (id < 0) return;
    axios({
      method: "put",
      url: "/image-api/" + id,
      baseURL: props.url,
      headers: {
        "Content-Type": "application/json",
      },
      params: {
        key: props.rkKey,
        api_token: props.apiToken,
      },
      data: JSON.stringify({
        action: "rename",
        name,
      }),
    })
      .then((res) => res.data)
      .then((data) => console.log(data))
      .catch((err) => console.log("error", err));
  }
  return (
    <>
      <Dialog open={err} onClose={() => setErr("")}>
        <DialogTitle>The photo cannot be uploaded to the server</DialogTitle>
        <DialogContent>
          <DialogContentText>
            <div dangerouslySetInnerHTML={{ __html: err }}></div>
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setErr("")} color="primary">
            Close
          </Button>
        </DialogActions>
      </Dialog>
      <Backdrop className={classes.backdrop} open={isLoading}>
        <CircularProgress />
      </Backdrop>
      <div>
        <Header
          title={title + " (" + images.length + ")"}
          bulletPoints={bulletPoints}
          imageLength={images.length}
          onRemoveAllImages={removeAllImagesHandle}
          buttonTitle={buttonTitle}
          addFiles={addFiles}
        />
        <div id="images" className={classes.images}>
          {images
            .sort((a, b) => (a.position > b.position ? 1 : -1))
            .map((image) => (
              <Image
                key={image.id}
                imgSrc={image.src}
                id={image.id}
                initialImageName={image.name}
                position={image.position}
                onImageRemove={removeImageHandle}
                onReorderImage={reorderImageHandle}
                onImageRename={imageRenameHandle}
                isLoading={!Number.isInteger(image.id)}
              />
            ))}
        </div>
      </div>
    </>
  );
}

function MaxItemsReachedException(message) {
  this.message = message;
  this.name = "MaxItemsReachedException";
}

export default RKImageUploader;
