import React, { useEffect, useState } from "react";
import AddBox from "./AddBox";
import List from "./List";

function RKTaglist({
  hiddenInput,
  items,
  setItems,
  maxItems,
  addButtonTitle,
  placeholder,
  listType,
  youtubeApiKey,
  vimeoApiKey,
  label,
}) {
  const [error, setError] = useState("");

  const isVideoList = listType && listType === "video";

  function handleAddItem(item) {
    if (error) setError("");
    const video = isVideoList && getVideo(item);

    // make sure max has not been reached yet
    if (!isNaN(parseInt(maxItems)) && maxItems <= items.length) {
      const s = maxItems > 1 ? "s" : "";
      setError(`Only ${maxItems} item${s} can be added.`);
      return;
    }

    // if it's video list, make sure it's in correct format
    if (isVideoList && !video) {
      setError(
        `"${item}" doesn't seem to be a correct YouTube or Vimeo URL. Please make sure the URL is correct and try again.`
      );
      return;
    }

    // made sure it's unique
    if (isVideoList) {
      if (!isUnique(video)) {
        setError(`You already added this video`);
        return;
      } else {
        setItems([...items, video]);
      }
    } else {
      if (!isUnique(item)) {
        setError(`You already added "${item}"`);
        return;
      } else {
        setItems([...items, item]);
      }
    }
  }

  function isUnique(item) {
    if (isVideoList) {
      return !items.some((testItem) => testItem.videoId === item.videoId);
    } else {
      return !items.some(
        (testItem) => testItem.toLowerCase() === item.toLowerCase()
      );
    }
  }

  /**
   * Verifies if the url is in correct
   * YouTube or Vimeo URL format
   *
   * @param {string} url The Vimeo or YouTube URL to check
   * @return {object|boolean} {provider: 'vimeo|youtube', videoId: 'VIDEO_ID'} or false in case of error format
   */
  function getVideo(url) {
    const youtubeRegex = /^.*((youtu.be\/)|(v\/)|(\/u\/\w\/)|(embed\/)|(watch\?))\??v?=?([^#&?]*).*/;
    const vimeoRegex = /^.*vimeo.com\/(.*\/)*([^#&?]*)/;
    let match;

    match = url.match(youtubeRegex);
    if (match && match[7].length == 11) {
      return { provider: "youtube", videoId: match[7] };
    }

    match = url.match(vimeoRegex);
    if (match && match[2].length > 0) {
      return { provider: "vimeo", videoId: match[2] };
    }

    return false;
  }

  function handleRemoveItem(item) {
    if (isVideoList) {
      const tempItems = [...items];
      tempItems.splice(
        tempItems.findIndex((s) => s.videoId === item),
        1
      );
      setItems(tempItems);
    } else {
      const tempItems = [...items];
      tempItems.splice(
        tempItems.findIndex((s) => s === item),
        1
      );
      setItems(tempItems);
    }
  }

  useEffect(() => {
    if (hiddenInput) {
      const hiddenInputElement = document.getElementById(hiddenInput);
      hiddenInputElement.value = JSON.stringify(items);
    }
  }, [items]);

  return (
    <div>
      <AddBox
        addButtonTitle={addButtonTitle}
        placeholder={placeholder}
        onAddItem={handleAddItem}
        label={label}
        error={error}
        setError={setError}
      />
      <List
        listType={listType}
        items={items}
        onRemoveItem={handleRemoveItem}
        youtubeApiKey={youtubeApiKey}
        vimeoApiKey={vimeoApiKey}
      />
    </div>
  );
}

export default RKTaglist;
