import React, { useState } from "react";
import uploadLogo from "./upload.svg";

function DragZone(props) {
  const [isDragHover, setIsDragHover] = useState(false);

  function dragOverHandle(e) {
    e.preventDefault();
  }

  function dragEnterHandle(e) {
    e.preventDefault();
    e.stopPropagation();
    setIsDragHover(true);
  }

  function dragLeaveHandle(e) {
    e.preventDefault();
    e.stopPropagation();
    setIsDragHover(false);
  }

  function dropHandle(e) {
    e.preventDefault();
    let dt = e.dataTransfer;
    let files = dt.files;
    setIsDragHover(false);

    props.addFiles([...files]);
  }

  return (
    <div>
      <div
        style={isDragHover ? null : { backgroundColor: "transparent" }}
        onDragEnter={dragEnterHandle}
        onDragLeave={dragLeaveHandle}
        onDrop={dropHandle}
        onDragOver={dragOverHandle}
      >
        <img src={uploadLogo} style={isDragHover ? { opacity: 1 } : null} />
        <h3>Drag your photos here...</h3>
      </div>
    </div>
  );
}

export default DragZone;
