import React from "react";
import Tag from "./Tag";
import Row from "./Row";
import Video from "./Video";
import { makeStyles } from "@material-ui/core/styles";

const useStyles = makeStyles((theme) => ({
  container: {
    display: "flex",
    justifyContent: "center",
  },
  tagList: {
    marginTop: theme.spacing(2),
  },
}));

function List({ items, onRemoveItem, listType, youtubeApiKey, vimeoApiKey }) {
  const classes = useStyles();
  switch (listType) {
    case "row":
      return (
        <table>
          <tbody>
            {items.map((item) => (
              <Row title={item} key={item} onRemoveItem={onRemoveItem} />
            ))}
          </tbody>
        </table>
      );
    case "video":
      return (
        <div className={classes.container}>
          {items.map((item) => (
            <Video
              video={item}
              key={item.videoId}
              onRemoveItem={onRemoveItem}
              youtubeApiKey={youtubeApiKey}
              vimeoApiKey={vimeoApiKey}
            />
          ))}
        </div>
      );
    default:
      return (
        <div className={classes.tagList}>
          {items.map((item) => (
            <Tag title={item} key={item} onRemoveItem={onRemoveItem} />
          ))}
        </div>
      );
  }
}

export default List;
