import { TextField } from "@material-ui/core";
import { Autocomplete } from "@material-ui/lab";
import Axios from "axios";
import { useEffect, useState } from "react";

import { makeStyles } from "@material-ui/core/styles";

const useStyles = makeStyles((theme) => ({
  input: {
    marginBottom: theme.spacing(2),
  },
}));

function PageSchool({
  allSchools,
  setAllSchools,
  apiToken,
  address,
  apiUrl,
  chosenSchools,
  setChosenSchools,
}) {
  const classes = useStyles();
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!allSchools && address.lat && address.lng && address.state) {
      setLoading(true);
      Axios({
        url: apiUrl + "/schools",
        params: {
          api_token: apiToken,
          lng: address.lng,
          lat: address.lat,
          state: address.state,
        },
      })
        .then((res) => res.data)
        .then((data) => {
          let schools = {
            elementarySchools: [],
            middleSchools: [],
            highSchools: [],
          };
          data.schools.forEach((school) => {
            if (school.elementary_school) {
              schools.elementarySchools.push(school.name);
            }
            if (school.middle_school) {
              schools.middleSchools.push(school.name);
            }
            if (school.high_school) {
              schools.highSchools.push(school.name);
            }
          });
          setAllSchools(schools);
        })
        .finally(() => setLoading(false));
    }
  }, []);
  return (
    <div>
      <Autocomplete
        freeSolo
        className={classes.input}
        options={(allSchools && allSchools.elementarySchools) || []}
        loading={loading}
        disableClearable
        value={chosenSchools.elementarySchool}
        onInputChange={(e, value) =>
          setChosenSchools({
            ...chosenSchools,
            elementarySchool: value,
          })
        }
        renderInput={(params) => (
          <TextField
            {...params}
            label="Elementary School"
            variant="outlined"
            InputProps={{ ...params.InputProps, type: "search" }}
          />
        )}
      />
      <Autocomplete
        freeSolo
        className={classes.input}
        options={(allSchools && allSchools.middleSchools) || []}
        loading={loading}
        value={chosenSchools.middleSchool}
        onInputChange={(e, value) =>
          setChosenSchools({
            ...chosenSchools,
            middleSchool: value,
          })
        }
        disableClearable
        renderInput={(params) => (
          <TextField
            {...params}
            label="Middle School"
            variant="outlined"
            InputProps={{ ...params.InputProps, type: "search" }}
          />
        )}
      />
      <Autocomplete
        freeSolo
        className={classes.input}
        options={(allSchools && allSchools.highSchools) || []}
        loading={loading}
        disableClearable
        value={chosenSchools.highSchool}
        onInputChange={(e, value) =>
          setChosenSchools({
            ...chosenSchools,
            highSchool: value,
          })
        }
        renderInput={(params) => (
          <TextField
            {...params}
            onChange={(e) =>
              setChosenSchools({ ...chosenSchools, highSchool: e.target.value })
            }
            label="High School"
            variant="outlined"
            InputProps={{ ...params.InputProps, type: "search" }}
          />
        )}
      />
    </div>
  );
}

export default PageSchool;
