import { useEffect, useState } from "react";
import {
  Card,
  CardMedia,
  CardActionArea,
  CardContent,
  CircularProgress,
  Backdrop,
  Typography,
} from "@material-ui/core";
import { makeStyles } from "@material-ui/core/styles";
import axios from "axios";

const useStyles = makeStyles((theme) => ({
  backdrop: {
    zIndex: theme.zIndex.drawer,
  },
  card: {
    width: 245,
    padding: theme.spacing(2),
    margin: theme.spacing(2),
    height: 245,
    position: "relative",
  },
  cardImage: {
    height: 0,
    paddingTop: "82%",
  },
  paperContainers: {
    display: "flex",
    flexWrap: "wrap",
  },
  featuredPhoto: {
    padding: 0,
  },
}));

function PageFeaturedPhoto(props) {
  const classes = useStyles();
  const [isLoading, setIsLoading] = useState(true);
  const [photos, setPhotos] = useState(null);
  const featuredPhoto = props.featuredPhoto;
  const setFeaturedPhoto = props.setFeaturedPhoto;

  // Download images that already exits on the server
  useEffect(() => {
    axios({
      method: "get",
      url: "/image-api",
      baseURL: props.url,
      params: {
        api_token: props.apiToken,
        key: props.rkKey,
      },
    })
      .then((res) => res.data)
      .then((imagesJson) => {
        for (let i = 0; i < imagesJson.length; i++) {
          imagesJson[i].src = "/" + imagesJson[i].image_url;
        }
        imagesJson.length && setPhotos(imagesJson);
      })
      .catch((err) => console.error(err))
      .finally(() => setIsLoading(false));
  }, []);

  return (
    <div>
      <Backdrop className={classes.backdrop} open={isLoading}>
        <CircularProgress />
      </Backdrop>
      {!isLoading && (
        <div>
          {photos ? (
            <div className={classes.paperContainers}>
              {photos.map((photo) => (
                <Card className={classes.card} key={photo.id}>
                  <CardActionArea onClick={() => setFeaturedPhoto(photo.id)}>
                    <CardMedia
                      image={photo.src}
                      className={classes.cardImage}
                    />
                  </CardActionArea>
                  {featuredPhoto === photo.id && (
                    <CardContent>
                      <Typography variant="subtitle1">
                        Featured Photo
                      </Typography>
                    </CardContent>
                  )}
                </Card>
              ))}
            </div>
          ) : (
            <Typography variant="h5">
              No photos have been uploaded yet.
            </Typography>
          )}
        </div>
      )}
    </div>
  );
}

export default PageFeaturedPhoto;
