import { Grid, TextField, MenuItem, InputAdornment } from "@material-ui/core";
import NumberFormat from "react-number-format";

// Custom react-number-format component
function SimpleNumber(props) {
  const { inputRef, onChange, max, thousandSeparator, ...other } = props;
  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            name: props.name,
            value: values.value,
          },
        });
      }}
      isAllowed={(values) => values.value.length < max}
      thousandSeparator={thousandSeparator}
      isNumericString
    />
  );
}

function YearFormat(props) {
  const { inputRef, onChange, ...other } = props;
  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            name: props.name,
            value: values.value,
          },
        });
      }}
      format="####"
    />
  );
}

