import React from "react";
import {
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  Button,
} from "@material-ui/core";

function Error({ message, setError }) {
  function handleClick() {
    setError("");
  }
  const showError = message && message.length > 0 ? true : false;
  return (
    <Dialog open={showError} onClose={handleClick}>
      <DialogContent>
        <DialogContentText>{message}</DialogContentText>
      </DialogContent>
      <DialogActions>
        <Button color="primary" onClick={handleClick}>
          OK
        </Button>
      </DialogActions>
    </Dialog>
  );
}

export default Error;
