import React, { useRef } from "react";
import locationIcon from "../images/location-icon.svg";
import poweredByGoogleLogo from "../images/power_google.png";
import { makeStyles } from "@material-ui/core/styles";

const useStyles = makeStyles((theme) => ({
  results: {
    padding: 0,
    margin: 0,
  },
  resultItem: {
    fontFamily: '"Roboto", "Helvetica", "Arial", sans-serif',
    borderBottom: "solid 1px #c4c4c4",
    listStyle: "none",
    margin: 0,
    padding: "1rem",
    "&:last-child": {
      borderBottom: "none",
      paddingBottom: 0,
    },
  },
  link: {
    textDecoration: "none",
    display: "flex",
    color: "#4a4a4a",
  },
  resultBox: {
    border: "solid 1px #c4c4c4",
    borderTop: "none",
    position: "absolute",
    borderRadius: "5px",
    zIndex: "100000",
    width: "100%",
    backgroundColor: "#fff",
  },
  poweredByGoogle: {
    textAlign: "right",
  },
  poweredByGoogleImg: {
    width: "100px",
    margin: "0.5rem",
  },
  locationIcon: {
    width: "1rem",
    marginRight: ".5rem",
  },
}));

function ResultBox({ results, onPlaceSelect }) {
  const poweredByGoogle = useRef(null);
  const classes = useStyles();
  function highlightMatched(address, matchedSubstrings) {
    const stringBefore = '<span style="font-weight:bold">';
    const stringAfter = "</span>";
    let offsetAdd = 0;
    let description = address;
    matchedSubstrings.forEach((sub) => {
      const highlight =
        stringBefore +
        description.substr(sub.offset + offsetAdd, sub.length) +
        stringAfter;
      const before = description.substr(0, sub.offset + offsetAdd);
      description = description.slice(sub.offset + offsetAdd + sub.length);
      description = before + highlight + description;
      offsetAdd += stringBefore.length + stringAfter.length;
    });
    return description;
  }

  if (!results || results.length === 0) {
    return null;
  }
  return (
    <div className={classes.resultBox}>
      <ul className={classes.results}>
        {results &&
          results.map((place) => (
            <li className={classes.resultItem} key={place.place_id}>
              <a
                href="#"
                className={classes.link}
                onClick={(e) =>
                  onPlaceSelect(e, place.place_id, poweredByGoogle)
                }
              >
                <img src={locationIcon} className={classes.locationIcon} />
                <span
                  dangerouslySetInnerHTML={{
                    __html: highlightMatched(
                      place.description,
                      place.matched_substrings
                    ),
                  }}
                ></span>
              </a>
            </li>
          ))}
      </ul>
      <div className={classes.poweredByGoogle} ref={poweredByGoogle}>
        <img src={poweredByGoogleLogo} className={classes.poweredByGoogleImg} />
      </div>
    </div>
  );
}

export default ResultBox;
